public class MessageHandler extends TextWebSocketHandler {
    private final AtomicLong sequenceGenerator = new AtomicLong(0);

    @Override
    protected void handleTextMessage(WebSocketSession session, TextMessage message) {
        long seq = sequenceGenerator.incrementAndGet();
        MessagePayload payload = deserialize(message.getPayload());
        payload.setSequenceId(seq);
        // Push to Kafka for persistence and ordering before broadcasting
        kafkaTemplate.send("chat-topic", payload.getConversationId(), payload);
    }
}
